#pragma once

// Generated by our converter fit from converter responses measured on isolated early-reflection
// taps of the REV7 / REV5 captures. Our
// own fit, not hardware data. Model: one low-pass stage used twice (anti-alias in, reconstruction out, as on
// the schematics) plus a first-order shelf on the output: era 7 the sample-and-hold droop, era 5 the remaining
// tilt (its droop is the hold itself, in the rate bridge; era 5 fitted on the realised chain). Do not edit.

namespace yrev::dsp::conv
{
    // Analogue section: (b0 s^2 + b1 s + b2) / (a0 s^2 + a1 s + a2), s normalised to 2 pi kRefHz, unity DC gain.
    // First-order sections have b0 = a0 = 0.
    struct AnalogSection
    {
        double b[3], a[3];
    };
    inline constexpr double kRefHz = 10000.0;

    // era7: ellip order 7 per stage, fc 11590 Hz, ripple 0.07 dB, stop 63.4 dB;
    // droop shelf pole 9276 Hz / zero 200000 Hz; whole-chain fit rms 0.32 dB.
    inline constexpr double kEra7WarpHz = 11590.0;
    inline constexpr AnalogSection kEra7Stage[] = {
        {{0.141965184287, -0, 1.44700044302}, {1, 0.132227634392, 1.44700044302}},
        {{0.317343364572, -0, 1.1615074876}, {1, 0.462441317031, 1.1615074876}},
        {{0.24473146761, -0, 0.645901108314}, {1, 0.899107465657, 0.645901108314}},
        {{0, 0, 0.575236089317}, {0, 1, 0.575236089317}},
    };
    inline constexpr AnalogSection kEra7Droop[] = {
        {{0, 0.046377747797, 0.927554393899}, {0, 1, 0.927554393899}},
    };

    // era5: butter order 2 per stage, fc 19300 Hz, ripple 0.22 dB, stop 52.0 dB;
    // tilt shelf (realised chain at 96 kHz, hold droop in the bridge) pole 9948 Hz / zero 43200 Hz; whole-chain fit rms 0.44 dB.
    inline constexpr double kEra5WarpHz = 19299.9;
    inline constexpr AnalogSection kEra5Stage[] = {
        {{0, 0, 3.7248716975}, {1, 2.72942180599, 3.7248716975}},
    };
    inline constexpr AnalogSection kEra5Droop[] = {
        {{0, 0.230273318867, 0.99478040238}, {0, 1, 0.99478040238}},
    };

} // namespace yrev::dsp::conv
